property.value:
(: Note: (: isWithin pattern :) pmd-kotlin:isWithin() does not exist in released PMD 7.28.0, experimental/future API.
   Replaced below with plain ancestor:: checks; see AvoidExcessiveClassloadingWithSaajSoap (remotingnextgen.xml)
   for more details. Grep for "(: isWithin pattern :)" to find/simplify all occurrences if isWithin() is ever
   actually released. :)
//PostfixUnaryExpression[
    PrimaryExpression/SimpleIdentifier/T-Identifier[@Text='synchronized']
    and PostfixUnarySuffix/CallSuffix
    and ancestor::FunctionBody
    and not(
        PostfixUnarySuffix/CallSuffix//LambdaLiteral//PostfixUnaryExpression[
            PrimaryExpression/SimpleIdentifier/T-Identifier/@Text =
                ancestor::ClassBody[1]//PropertyDeclaration[
                    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
                ]/VariableDeclaration/@Identifier
        ]
    )
    and not(
        PostfixUnarySuffix/CallSuffix//LambdaLiteral//Assignment[
            (DirectlyAssignableExpression|AssignableExpression)//T-Identifier/@Text =
                ancestor::ClassBody[1]//PropertyDeclaration[
                    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
                ]/VariableDeclaration/@Identifier
        ]
    )
]

rule.example:
class SyncService {
    fun bad(): String {
        var localVar = "start"
        synchronized(this) {
            localVar = "updated" // bad
        }
        return localVar
    }
}

fun collectBad(completionService: CompletionService<List<Any>>): Future<List<Any>> {
    return completionService.take() // bad
}

fun collectGood(completionService: CompletionService<List<Any>>): Future<List<Any>>? {
    return completionService.poll(3L, TimeUnit.SECONDS) // good
}

