        starts-with(@Name, 'org.springframework.web.client')
        or starts-with(@Name, 'org.apache.commons.httpclient')
        or starts-with(@Name, 'org.apache.http')
    ]
]//PostfixUnaryExpression[
    pmd-kotlin:matchesSig('java.util.Collection#parallelStream()')
