rule.example:

import org.springframework.web.client.RestTemplate
class Service(val restTemplate: RestTemplate) {
    val items = listOf("a", "b")
    fun bad() = items.parallelStream().forEach { restTemplate.getForObject("/api/$it", String::class.java) } // bad: blocks common pool
    fun good() = kotlinx.coroutines.runBlocking { items.map { kotlinx.coroutines.async(kotlinx.coroutines.Dispatchers.IO) { restTemplate.getForObject("/api/$it", String::class.java) } }.map { it.await() } } // ok: IO dispatcher
}

import java.util.concurrent.Callable
import java.util.concurrent.ExecutorService
import java.util.concurrent.Future
import java.util.concurrent.TimeUnit

class TaskRunner {
    fun invokeAllBad(executor: ExecutorService, callables: Collection<Callable<String>>): List<Future<String>> {
        return executor.invokeAll(callables) // bad
    }

    fun invokeAllGood(executor: ExecutorService, callables: Collection<Callable<String>>): List<Future<String>> {
        return executor.invokeAll(callables, 30, TimeUnit.SECONDS) // good
    }
}

class StreamService {
    fun bad(list: List<String>) {
        list.parallelStream().forEach { println(it) } // bad
    }

    fun good(list: List<String>) {
        list.asSequence().forEach { println(it) } // good
    }
}

fun getOrdersBad(futures: List<CompletableFuture<Order>>): List<Order> {
    return futures
        .filter { it.isDone && !it.isCompletedExceptionally }
        .map { it.join() } // bad, no timeout provided
}

fun getOrdersGood(futures: List<CompletableFuture<Order>>): List<Order> {
    val allResult = CompletableFuture.allOf(*futures.toTypedArray())
    try {
        allResult.get(5L, TimeUnit.SECONDS) // good - timeout
    } catch (e: Exception) { }
    return futures
        .filter { it.isDone && !it.isCompletedExceptionally }
        .map { it.join() } // good - timeout provided above
}

@Service
class MyService {
    @Value("\${batchService.http.url}")
    var url: String = ""

    @GuardedBy("lock")
    var guardedUrl: String = ""

    fun setUrlBad(url: String) {
        this.url = url // bad: unguarded accessor method
    }

    @Synchronized
    fun setUrlGood(url: String) {
        this.url = url // good: synchronized accessor method
    }
}

class Foo {
    private val asyncPool = Executors.newFixedThreadPool(8)

    fun bad(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync { isAccountBlocked(it) } // bad, uses common pool
        }
    }

    fun good(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync({ isAccountBlocked(it) }, asyncPool) // good
        }
    }
}

class Bad {
    var date: String = ""

    fun setDate(d: String) {
        date = d // bad - synchronized used in class
    }

    @Synchronized
    fun getDate(): String = date
}

@NotThreadSafe
class Good {
    var date: String = ""

    fun setDate(d: String) {
        date = d // good - @NotThreadSafe
    }
}

@Controller
class RootController {

    var baskets: List<Any> = listOf()          // bad, not private
    protected var baskets2: List<Any> = listOf() // bad, not private
    val baskets3: List<Any> = listOf()          // good, val (final)
    private var baskets4: List<Any> = listOf()  // good, private

    @Autowired
    lateinit var baskets5: List<Any>           // allowed, injected
}

@Component
class Bad {
    var url: String = ""  // bad, unguarded var field

    fun setUrlBad(url: String) {
        this.url = url
    }
}

@Component
class BadMutableTypes {
    val date: Date = Date()                           // bad, Date is mutable
    @Volatile var strBuilder: StringBuilder = StringBuilder() // bad, mutable type
    val map: HashMap<String, String> = HashMap()      // bad, mutable collection

    @GuardedBy("this")
    val guardedMap: HashMap<String, String> = HashMap() // good, guarded
}

class Bad {
    var date: String = ""  // bad, unguarded var field in class using synchronized

    fun setDate(d: String) {
        date = d
    }

    @Synchronized
    fun getDate(): String = date
}

class Good {
    @net.jcip.annotations.GuardedBy("this")
    var date: String = ""  // good, guarded

    @Synchronized
    fun getDate(): String = date
}


class Bad {
    companion object {
        var count: Int = 0 // bad: mutable static field
    }
}
class Good {
    companion object {
        val MAX: Int = 100 // ok: immutable
        @Volatile
        var running: Boolean = false // ok: volatile
    }
}


import javax.xml.parsers.DocumentBuilderFactory

class Bad {
    companion object {
        val dbFactory: DocumentBuilderFactory = DocumentBuilderFactory.newInstance() // bad
    }
    fun parse(xml: String) {
        val localFactory = DocumentBuilderFactory.newInstance() // ok: local variable
    }
}

